/* @lc app=leetcode id=4026 lang=kotlin */ class Solution { fun maximumGap(skill: String, station: String): Int = skill.fold(listOf(-1)) { acc, c -> acc + station.indexOf(c, acc.last() + 1) }.drop(1).let { L -> skill.reversed().fold(listOf(station.length)) { acc, c -> acc + station.lastIndexOf(c, acc.last() - 1) }.drop(1).reversed().let { R -> (1 until skill.length).maxOfOrNull { R[it] - L[it - 1] } ?: 0 } } }